insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000001','numbers','مقارنة الكسور بالمعنى','أي تفسير يبرهن أن ٧⁄١٢ أصغر من ٣⁄٤؟','["لأن ٧ أصغر من ٣", "لأن ٣⁄٤ يساوي ٩⁄١٢، و٧⁄١٢ أصغر من ٩⁄١٢", "لأن ١٢ أكبر من ٤", "لأن الفرق بين البسطين يساوي ٤"]'::jsonb,1,'نوحّد المقام: ٣⁄٤ = ٩⁄١٢، ومن ثم ٧⁄١٢ < ٩⁄١٢.','مقارنة البسطين أو المقامين منفردين.','حوّل أحد الكسرين إلى مقام مشترك أو استخدم كسرًا مرجعيًا.','متوسط',true,100,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000002','pedagogy','تحليل خطأ إعادة التجميع','كتب متعلم: ٤٠٢ − ١٨٧ = ٣٨٥؛ لأنه طرح الرقم الأصغر من الأكبر في كل منزلة. ما التدخل التعليمي الأفضل أولًا؟','["إعطاؤه عشر مسائل مماثلة", "مطالبته بحفظ خطوات الخوارزمية", "تمثيل ٤٠٢ بقطع القيمة المنزلية وإعادة التجميع مع تقدير الناتج", "السماح له باستخدام الآلة الحاسبة"]'::jsonb,2,'التمثيل بالقيمة المنزلية يكشف سبب إعادة التجميع، والتقدير يوضح أن الناتج غير معقول.','زيادة التدريب على خوارزمية لم يفهم معناها.','شخّص التصور الخاطئ ثم اختر تمثيلًا يكشفه.','متقدم',true,99,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000003','algebra','قاعدة الحد النوني','بدأ نمط عددي بالقيم: ٥، ٨، ١١، ١٤، … فما العبارة التي تمثل الحد النوني؟','["٣ن + ٢", "٣ن + ٥", "٥ن − ٢", "ن + ٤"]'::jsonb,0,'الفرق ثابت ٣، وعند ن=١ يجب أن تكون القيمة ٥؛ لذا ٣ن+٢.','اعتبار الحد الأول هو الثابت مباشرة.','القاعدة = الفرق×ن + (الحد الأول−الفرق).','متوسط',true,98,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000004','proportion','تمييز التناسب الطردي','أي مجموعة أزواج تمثل علاقة تناسب طردي ثابتة؟','["(٢،٦)، (٤،١٢)، (٦،١٨)", "(٢،٦)، (٤،١٠)، (٦،١٤)", "(١،٣)، (٢،٥)، (٣،٧)", "(٢،٤)، (٣،٩)، (٤،١٦)"]'::jsonb,0,'النسبة ص⁄س ثابتة وتساوي ٣ في جميع الأزواج.','الاكتفاء بوجود نمط منتظم دون ثبات النسبة.','احسب ص÷س لكل زوج.','متوسط',true,97,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000005','geometry','عامل القياس والمساحة','إذا زاد طول ضلع مربع بنسبة ٥٠٪، فكم تكون نسبة الزيادة في مساحته؟','["٥٠٪", "٧٥٪", "١٠٠٪", "١٢٥٪"]'::jsonb,3,'عامل القياس ١٫٥، وعامل المساحة ١٫٥²=٢٫٢٥؛ أي زيادة ١٢٥٪.','تطبيق نسبة الزيادة الخطية نفسها على المساحة.','المساحة تتغير بمربع عامل القياس.','متقدم',true,96,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000006','measurement','استنتاج الأبعاد','مستطيل مساحته ٤٨ وحدة مربعة ومحيطه ٢٨ وحدة. ما بعداه؟','["٤ و١٢", "٦ و٨", "٣ و١٦", "٧ و٧"]'::jsonb,1,'مجموع البعدين ١٤ وحاصل ضربهما ٤٨، فيتحقق ذلك للعددين ٦ و٨.','استخدام شرط واحد فقط من المساحة أو المحيط.','ابحث عن عاملين للـ٤٨ مجموعهما نصف المحيط.','متقدم',true,95,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000007','statistics','تصحيح المتوسط','متوسط ٨ قيم يساوي ١٥. اكتُشف أن قيمة سُجلت ٩ بدلًا من ١٧. ما المتوسط الصحيح؟','["١٥", "١٦", "١٧", "٢٣"]'::jsonb,1,'المجموع المسجل ١٢٠، نضيف فرق التصحيح ٨ فيصبح ١٢٨، ثم ١٢٨÷٨=١٦.','إضافة القيمة الصحيحة دون طرح القيمة الخاطئة.','صحح المجموع أولًا ثم اقسم.','متقدم',true,94,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000008','statistics','احتمال دون إرجاع','صندوق فيه ٣ كرات حمراء وكرتان زرقاوان. سُحبت كرتان دون إرجاع. ما احتمال أن تكونا زرقاوين؟','["١⁄٥", "١⁄١٠", "٢⁄٥", "١⁄٤"]'::jsonb,1,'٢⁄٥ × ١⁄٤ = ١⁄١٠.','إبقاء المقام ٥ في السحب الثاني.','حدّث عدد العناصر بعد السحب الأول.','متقدم',true,93,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000009','numbers','معنى قسمة الكسور','أي تمثيل يوضح بصورة أفضل معنى ٢⁄٣ ÷ ١⁄٦؟','["وضع ٢⁄٣ على خط أعداد وعدّ المقاطع التي طول كل منها ١⁄٦", "جمع ٢⁄٣ و١⁄٦", "رسم ٢⁄٣ من ستة أشكال فقط", "مقارنة المقامين دون تمثيل"]'::jsonb,0,'القسمة تسأل: كم جزءًا حجمه ١⁄٦ يوجد داخل ٢⁄٣؟ والجواب ٤.','الاعتماد على قاعدة اقلب واضرب دون فهم المعنى.','حوّل القسمة إلى سؤال: كم مجموعة؟','متقدم',true,92,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000010','pedagogy','الفهم العلاقي للمساواة','أي سؤال يقيس الفهم العلاقي لعلامة المساواة بصورة أفضل؟','["احسب ٨+٤", "اكتب ناتج ١٢−٥", "ضع عددًا في □ ليصبح ٨+٤ = □+٥ صحيحًا، واشرح", "أكمل جدول الجمع"]'::jsonb,2,'يقيس تكافؤ الطرفين لا مجرد تنفيذ عملية وكتابة الناتج.','اختيار سؤال إجرائي لا يكشف معنى المساواة.','اختر مهمة تتطلب موازنة طرفين وتفسيرًا.','متقدم',true,91,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000011','numbers','تحويل عدد عشري','ما أبسط صورة للكسر المكافئ للعدد ٠٫٣٧٥؟','["٣⁄٥", "٣⁄٨", "٣٧⁄١٠٠", "٥⁄٨"]'::jsonb,1,'٠٫٣٧٥=٣٧٥⁄١٠٠٠، وبالقسمة على ١٢٥ نحصل على ٣⁄٨.','حذف الأصفار دون تبسيط صحيح.','اكتب العدد على قوة ١٠ ثم اختصر.','متقدم',false,90,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000012','numbers','القاسم المشترك في سياق','لدى معلم ٤٨ بطاقة حمراء و٦٠ زرقاء ويريد أكبر عدد من الحزم المتماثلة دون بقايا. كم حزمة؟','["٦", "١٠", "١٢", "٢٤"]'::jsonb,2,'أكبر عدد للحزم هو ق.م.أ(٤٨،٦٠)=١٢.','اختيار المضاعف المشترك بدل القاسم المشترك.','عبارة أكبر عدد من مجموعات متساوية تشير إلى ق.م.أ.','متقدم',false,89,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000013','numbers','تفسير الباقي','ينتقل ١٥٧ متعلمًا في حافلات تسع كل واحدة ٢٤. ما أقل عدد من الحافلات؟','["٦", "٧", "٨", "٦ والباقي ١٣"]'::jsonb,1,'١٥٧÷٢٤=٦ والباقي ١٣، لذا نحتاج حافلة سابعة.','ترك الباقي دون تفسير في السياق.','إذا بقي أشخاص فقرّب عدد الحافلات إلى الأعلى.','متوسط',false,88,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000014','algebra','قاعدة دالة من جدول','قيم س: −١، ٠، ١، ٢ وتقابلها ص: ٥، ٣، ١، −١. ما قاعدة الدالة؟','["ص=٢س+٣", "ص=−٢س+٣", "ص=−٢س+٥", "ص=٣س−٢"]'::jsonb,1,'الميل −٢، والمقطع عند س=٠ يساوي ٣.','استخدام أول قيمة ص بوصفها المقطع دون الرجوع إلى س=٠.','استخرج معدل التغير ثم قيمة ص عند س=٠.','متقدم',false,90,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000015','algebra','عكس علاقة خطية','إذا كانت ص=٣س+٤، فأي عبارة صحيحة لس بدلالة ص؟','["س=(ص+٤)⁄٣", "س=٣ص−٤", "س=(ص−٤)⁄٣", "س=ص⁄٣−٤"]'::jsonb,2,'نطرح ٤ ثم نقسم على ٣: س=(ص−٤)⁄٣.','عكس العمليات دون المحافظة على ترتيبها.','اعزل المتغير بعكس العمليات من الخارج إلى الداخل.','متقدم',false,88,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000016','proportion','زيادتان متعاكستان','زاد سعر منتج ٢٠٪ ثم انخفض السعر الجديد ٢٠٪. ما التغير الكلي؟','["عاد للأصل", "انخفض ٤٪", "زاد ٤٪", "انخفض ٢٠٪"]'::jsonb,1,'من ١٠٠ إلى ١٢٠ ثم ينقص ٢٤ فيصبح ٩٦؛ انخفاض ٤٪.','جمع +٢٠٪ و−٢٠٪ على أساس واحد.','استخدم قيمة افتراضية ١٠٠.','متقدم',false,91,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000017','proportion','مقياس الرسم','مخطط بمقياس ١:٥٠ يظهر جدارًا طوله ٨ سم. ما طوله الحقيقي؟','["٤٠ سم", "٤ م", "٤٠ م", "٤٠٠ م"]'::jsonb,1,'٨×٥٠=٤٠٠ سم=٤ م.','نسيان تحويل السنتيمتر إلى متر.','اضرب بالمقياس ثم وحّد الوحدة.','متوسط',false,86,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000018','geometry','الزاوية الخارجية','زاويتان داخليتان بعيدتان عن زاوية خارجية في مثلث قياسهما ٤٨° و٦٧°. ما قياس الزاوية الخارجية؟','["٦٧°", "١٠٥°", "١١٥°", "١٨٠°"]'::jsonb,2,'الزاوية الخارجية تساوي مجموع الزاويتين الداخليتين البعيدتين: ١١٥°.','طرح المجموع من ١٨٠ بلا حاجة.','الخارجية = مجموع الداخليتين البعيدتين.','متوسط',false,87,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000019','geometry','خصائص الدوران','أي خاصية لا يلزم أن تبقى ثابتة بعد دوران شكل ٩٠°؟','["الأطوال", "قياسات الزوايا", "المساحة", "الاتجاه بالنسبة للمحاور"]'::jsonb,3,'الدوران يحفظ التطابق لكنه يغير الاتجاه والموقع غالبًا.','الخلط بين خصائص الشكل وموضعه.','التحويلات المتطابقة تحفظ القياس لا الاتجاه المطلق.','متقدم',false,85,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000020','measurement','حجم منشور عشري','صندوق أبعاده ٢٫٥م، ١٫٢م، ٠٫٨م. ما حجمه؟','["٢٫٤ م³", "٣٫٠ م³", "٤٫٥ م³", "٢٤ م³"]'::jsonb,0,'٢٫٥×١٫٢×٠٫٨=٢٫٤ م³.','إهمال الوحدة المكعبة أو موضع الفاصلة.','اجمع ضرب عددين سهلين أولًا: ٢٫٥×١٫٢=٣.','متقدم',false,89,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000021','measurement','المحيط الثابت','أي مستطيل محيطه ٢٤ وحدة يحقق أكبر مساحة؟','["١×١١", "٣×٩", "٥×٧", "٦×٦"]'::jsonb,3,'عند ثبات المحيط تكون المساحة العظمى للمربع: ٦×٦=٣٦.','الاعتقاد أن زيادة أحد البعدين تزيد المساحة دائمًا.','مع مجموع ثابت، يتعاظم الضرب عند تقارب العددين.','متقدم',false,87,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000022','statistics','القيمة المتطرفة','للبيانات ٤،٥،٦،٦،٧،٨،٣٠؛ أي مقياس يصف المركز أفضل؟','["المتوسط", "الوسيط", "المدى", "الانحراف المعياري"]'::jsonb,1,'الوسيط ٦ أقل تأثرًا بالقيمة المتطرفة ٣٠.','اختيار المتوسط تلقائيًا لكل مجموعة بيانات.','عند وجود قيمة متطرفة قارن المتوسط بالوسيط.','متقدم',false,90,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000023','statistics','تحيز العينة','سأل مسؤول عن رضا المقصف الطلاب الذين اشتروا منه فقط. ما نوع المشكلة؟','["حجم العينة كبير", "العينة متحيزة", "لا يمكن حساب المتوسط", "السؤال مفتوح"]'::jsonb,1,'استبعد من لم يشتروا وربما كانوا الأقل رضا.','اعتبار كثرة المشاركين كافية لضمان التمثيل.','اسأل: من لم تتح له فرصة الدخول في العينة؟','متقدم',false,88,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000024','pedagogy','المحيط والمساحة','يعتقد متعلم أن الأشكال ذات المحيط نفسه لها المساحة نفسها. ما النشاط الأقوى؟','["إعطاؤه القاعدة للحفظ", "تكوين مستطيلات مختلفة بخيط ثابت وحساب مساحاتها", "تكليفه بحل عشر مسائل مباشرة", "عرض تعريف المحيط فقط"]'::jsonb,1,'التجربة بمحيط ثابت ومساحات مختلفة تكشف التصور الخاطئ بصريًا وعدديًا.','تصحيح الإجابة دون معالجة الفكرة الأصلية.','اختر نشاطًا يولّد مثالًا مضادًا محسوسًا.','متقدم',false,95,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000025','pedagogy','التقويم التكويني','بعد شرح مفهوم التناسب، أي إجراء يقدم دليلًا أسرع على فهم جميع المتعلمين؟','["سؤال شفهي لمتعلم واحد", "واجب منزلي طويل", "بطاقة خروج بسؤال يطلب التبرير", "إعادة الشرح بالطريقة نفسها"]'::jsonb,2,'بطاقة الخروج تجمع دليلًا فرديًا سريعًا ويمكن تحليل أنماط الإجابات.','الاعتماد على إجابة طالب واحد لتمثيل الصف.','اختر أداة قصيرة فردية تكشف التفكير.','متقدم',false,93,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
insert into public.questions(id,skill_id,title,question_text,options,correct_index,explanation,trap,quick_method,difficulty,is_diagnostic,priority,active) values('00000000-0000-4000-8000-000000000026','pedagogy','اختيار التمثيل','أي تمثيل أنسب لبدء تعليم ضرب كسر في عدد صحيح؟','["قاعدة اضرب البسط فقط", "نموذج مجموعات متكررة أو شريط كسري", "آلة حاسبة", "حفظ أمثلة محلولة"]'::jsonb,1,'النموذج يربط الضرب بالجمع المتكرر ويُظهر معنى الناتج.','بدء التعليم بالخوارزمية قبل المعنى.','ابدأ بتمثيل يكشف بنية العملية.','متقدم',false,92,true) on conflict(id) do update set skill_id=excluded.skill_id,title=excluded.title,question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,trap=excluded.trap,quick_method=excluded.quick_method,difficulty=excluded.difficulty,is_diagnostic=excluded.is_diagnostic,priority=excluded.priority,active=true;
